verification_tests:
from target import racks_conflict


def test_overlapping_reservations_conflict():
    assert racks_conflict({"start": 10, "end": 20}, {"start": 15, "end": 25}) is True


def test_touching_reservations_do_not_conflict():
    assert racks_conflict({"start": 10, "end": 20}, {"start": 20, "end": 30}) is False


def test_empty_reservation_never_conflicts():
    assert racks_conflict({"start": 10, "end": 10}, {"start": 1, "end": 100}) is False
